class Solution {
    public double findMedianSortedArrays(int[] nums1, int[] nums2) {
        if (nums1.length > nums2.length) {
            return findMedianSortedArrays(nums2, nums1);    // 保证在短的数组上二分
        }
        int m = nums1.length, n = nums2.length;
        int half = (m + n + 1) / 2;                     // 左半边一共要有多少个数
        int lo = 0, hi = m;
        while (true) {
            int i = (lo + hi) / 2;                      // nums1 左边取 i 个
            int j = half - i;                           // nums2 左边取 j 个
            int l1 = i > 0 ? nums1[i - 1] : Integer.MIN_VALUE;
            int r1 = i < m ? nums1[i] : Integer.MAX_VALUE;
            int l2 = j > 0 ? nums2[j - 1] : Integer.MIN_VALUE;
            int r2 = j < n ? nums2[j] : Integer.MAX_VALUE;
            if (l1 > r2) {
                hi = i - 1;                             // nums1 切得太靠右
            } else if (l2 > r1) {
                lo = i + 1;                             // nums1 切得太靠左
            } else {
                if ((m + n) % 2 == 1) {
                    return Math.max(l1, l2);
                }
                return (Math.max(l1, l2) + (double) Math.min(r1, r2)) / 2;
            }
        }
    }
}

